<tr><td><label>روش تسویه<select name="payment_items[<?php echo esc_attr($paymentIndex); ?>][method]"><?php foreach(['cash'=>'نقد','card'=>'پوز / کارت','transfer'=>'حواله','cheque'=>'چک'] as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($paymentRow['method']??'cash',$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label>حساب بانک / صندوق<select name="payment_items[<?php echo esc_attr($paymentIndex); ?>][treasury_account_id]"><option value="0">انتخاب حساب</option><?php foreach($paymentAccounts as $account): ?><option value="<?php echo (int)$account['id']; ?>" <?php selected($paymentRow['treasury_account_id']??0,$account['id']); ?>><?php echo esc_html($account['name']); ?></option><?php endforeach; ?></select></label></td>
<td><label>مبلغ تسویه<input name="payment_items[<?php echo esc_attr($paymentIndex); ?>][amount]" inputmode="decimal" value="<?php echo esc_attr($paymentRow['amount']??''); ?>"></label><label>شمارهٔ پیگیری<input name="payment_items[<?php echo esc_attr($paymentIndex); ?>][reference]" maxlength="80" value="<?php echo esc_attr($paymentRow['reference']??''); ?>"></label></td>
<td><label>شماره چک<input name="payment_items[<?php echo esc_attr($paymentIndex); ?>][cheque_no]" value="<?php echo esc_attr($paymentRow['cheque_no']??''); ?>" maxlength="80"></label><label>بانک چک<input name="payment_items[<?php echo esc_attr($paymentIndex); ?>][bank_name]" value="<?php echo esc_attr($paymentRow['bank_name']??''); ?>" maxlength="100"></label><label>سررسید چک<input name="payment_items[<?php echo esc_attr($paymentIndex); ?>][due_date]" data-jalali value="<?php echo esc_attr($paymentRow['due_date']??''); ?>"></label></td>
<td><button type="button" class="btn btn-outline" data-business-remove>حذف روش</button></td></tr>
